// Package integration runs the REAL components together: a real Mosquitto
// broker (per-device credentials + ACL generated by aerolab-seed), the real
// `edge` binary as a separate process (so it can be SIGKILLed like a power
// cut), and the simulated ESP32 fleet. Tests skip - never silently pass -
// when mosquitto is not installed.
package integration

import (
	"bytes"
	"database/sql"
	"encoding/json"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"syscall"
	"testing"
	"time"

	_ "modernc.org/sqlite"

	"github.com/mehdibouchachi/aerolab-v2/simulator/esp32"
	"github.com/mehdibouchachi/aerolab-v2/simulator/seed"
)

var (
	edgeBin   string
	buildOnce sync.Once
	buildErr  error
)

func repoRoot() string {
	wd, _ := os.Getwd()
	for d := wd; d != "/"; d = filepath.Dir(d) {
		if _, err := os.Stat(filepath.Join(d, "go.work")); err == nil {
			return d
		}
	}
	panic("go.work not found")
}

func buildEdge(t *testing.T) string {
	buildOnce.Do(func() {
		dir, err := os.MkdirTemp("", "aerolab-edge-bin-")
		if err != nil {
			buildErr = err
			return
		}
		edgeBin = filepath.Join(dir, "edge")
		cmd := exec.Command("go", "build", "-o", edgeBin, "./cmd/edge")
		cmd.Dir = filepath.Join(repoRoot(), "services", "edge-api")
		out, err := cmd.CombinedOutput()
		if err != nil {
			buildErr = fmt.Errorf("build edge: %v\n%s", err, out)
		}
	})
	if buildErr != nil {
		t.Fatal(buildErr)
	}
	return edgeBin
}

func freePort(t *testing.T) int {
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	defer l.Close()
	return l.Addr().(*net.TCPAddr).Port
}

// stack is one complete site.
type stack struct {
	t          *testing.T
	dir        string
	prov       *seed.Result
	brokerPort int
	broker     *exec.Cmd
	edge       *exec.Cmd
	edgePort   int
	edgeEnv    map[string]string
	fleet      *esp32.Fleet
	tok        string
}

func newStack(t *testing.T, devices int) *stack {
	t.Helper()
	if _, err := exec.LookPath("mosquitto"); err != nil {
		t.Skip("mosquitto not installed: integration tests need a real broker")
	}
	s := &stack{t: t, dir: t.TempDir(), brokerPort: freePort(t), edgePort: freePort(t)}
	prov, err := seed.Provision(seed.Options{OutDir: filepath.Join(s.dir, "dev"), SiteID: "site-it-01", Devices: devices, BrokerPort: s.brokerPort})
	if err != nil {
		t.Fatal(err)
	}
	s.prov = prov
	t.Cleanup(s.cleanup)
	return s
}

func (s *stack) startBroker() {
	s.t.Helper()
	cmd := exec.Command("mosquitto", "-c", s.prov.MosquittoConf)
	cmd.Stdout, cmd.Stderr = io.Discard, io.Discard
	if err := cmd.Start(); err != nil {
		s.t.Fatal(err)
	}
	s.broker = cmd
	waitTCP(s.t, s.brokerPort)
}

func (s *stack) stopBroker() {
	if s.broker != nil {
		_ = s.broker.Process.Kill()
		_, _ = s.broker.Process.Wait()
		s.broker = nil
	}
}

func waitTCP(t *testing.T, port int) {
	t.Helper()
	deadline := time.Now().Add(10 * time.Second)
	for time.Now().Before(deadline) {
		if c, err := net.DialTimeout("tcp", fmt.Sprintf("127.0.0.1:%d", port), 200*time.Millisecond); err == nil {
			c.Close()
			return
		}
		time.Sleep(50 * time.Millisecond)
	}
	t.Fatalf("port %d never opened", port)
}

func (s *stack) dbPath() string { return filepath.Join(s.dir, "edge.db") }

func (s *stack) startEdge(extra map[string]string) {
	s.t.Helper()
	bin := buildEdge(s.t)
	env := os.Environ()
	set := map[string]string{
		"AEROLAB_SITE_ID": s.prov.SiteID, "AEROLAB_SITE_NAME": "IT-SITE-SIMULATED", "AEROLAB_HTTP_ADDR": fmt.Sprintf("127.0.0.1:%d", s.edgePort),
		"AEROLAB_DB_PATH": s.dbPath(), "AEROLAB_MQTT_URL": s.prov.BrokerURL, "AEROLAB_MQTT_USER": seed.EdgeMQTTUser, "AEROLAB_MQTT_PASSWORD": s.prov.EdgePassword,
		"AEROLAB_ALLOW_SIMULATED_DATA": "true", "AEROLAB_PROVISION_FILE": s.prov.CredsFile,
		"AEROLAB_BOOTSTRAP_ADMIN_USER": s.prov.AdminUser, "AEROLAB_BOOTSTRAP_ADMIN_PASSWORD": s.prov.AdminPassword,
		"AEROLAB_STALE_AFTER": "3s", "AEROLAB_COMMAND_RETRY": "1s", "AEROLAB_COMMAND_TTL": "30s", "AEROLAB_MIN_FREE_MIB": "1",
	}
	for k, v := range extra {
		set[k] = v
	}
	s.edgeEnv = set
	for k, v := range set {
		if v != "" {
			env = append(env, k+"="+v)
		}
	}
	cmd := exec.Command(bin, "serve")
	cmd.Env = env
	logf, _ := os.Create(filepath.Join(s.dir, "edge.log"))
	cmd.Stdout, cmd.Stderr = logf, logf
	if err := cmd.Start(); err != nil {
		s.t.Fatal(err)
	}
	s.edge = cmd
	waitTCP(s.t, s.edgePort)
	s.tok = ""
}

// killEdge sends SIGKILL: no graceful shutdown, like losing power.
func (s *stack) killEdge() {
	if s.edge != nil {
		_ = s.edge.Process.Signal(syscall.SIGKILL)
		_, _ = s.edge.Process.Wait()
		s.edge = nil
	}
}

func (s *stack) stopEdgeGracefully() {
	if s.edge != nil {
		_ = s.edge.Process.Signal(syscall.SIGTERM)
		done := make(chan struct{})
		go func() { _, _ = s.edge.Process.Wait(); close(done) }()
		select {
		case <-done:
		case <-time.After(10 * time.Second):
			_ = s.edge.Process.Kill()
		}
		s.edge = nil
	}
}

// startFleet runs n devices with accelerated timing (documented in tests).
func (s *stack) startFleet(n int, mut func(*esp32.Config)) {
	s.t.Helper()
	f := esp32.NewFleet()
	for i := 0; i < n; i++ {
		c := s.prov.Devices[i]
		cfg := esp32.Config{SiteID: s.prov.SiteID, DeviceID: c.DeviceID, UnitID: c.UnitID, BrokerURL: s.prov.BrokerURL, Username: c.DeviceID, Password: c.Password,
			HeartbeatEvery: 300 * time.Millisecond, TelemetryEvery: 400 * time.Millisecond, ControlTick: 20 * time.Millisecond, SelfCheckTime: 100 * time.Millisecond,
			ReceiptTimeout: 2 * time.Second, ReconnectMin: 200 * time.Millisecond, ReconnectMax: time.Second, Seed: int64(i + 1)}
		if mut != nil {
			mut(&cfg)
		}
		f.Add(esp32.New(cfg))
	}
	s.fleet = f
	ctx, cancel := contextWithCancel()
	s.t.Cleanup(func() { cancel(); f.Stop() })
	f.Start(ctx)
}

func (s *stack) cleanup() {
	if s.fleet != nil {
		s.fleet.Stop()
	}
	if s.edge != nil {
		_ = s.edge.Process.Kill()
		_, _ = s.edge.Process.Wait()
	}
	s.stopBroker()
	if s.t.Failed() {
		if b, err := os.ReadFile(filepath.Join(s.dir, "edge.log")); err == nil {
			s.t.Logf("---- edge.log (tail) ----\n%s", tail(string(b), 3000))
		}
	}
}

func tail(s string, n int) string {
	if len(s) > n {
		return s[len(s)-n:]
	}
	return s
}

// ------------------------------------------------------------------- HTTP

func (s *stack) url(p string) string { return fmt.Sprintf("http://127.0.0.1:%d%s", s.edgePort, p) }

func (s *stack) login(user, pass string) string {
	s.t.Helper()
	var out struct{ Token string }
	code := s.call("POST", "/api/v1/local/auth/login", "", map[string]string{"username": user, "password": pass}, &out)
	if code != 200 {
		s.t.Fatalf("login %s: %d", user, code)
	}
	return out.Token
}

func (s *stack) admin() string {
	if s.tok == "" {
		s.tok = s.login(s.prov.AdminUser, s.prov.AdminPassword)
	}
	return s.tok
}

func (s *stack) call(method, path, tok string, body, out any) int {
	s.t.Helper()
	var rd io.Reader
	if body != nil {
		b, _ := json.Marshal(body)
		rd = bytes.NewReader(b)
	}
	req, _ := http.NewRequest(method, s.url(path), rd)
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	if tok != "" {
		req.Header.Set("Authorization", "Bearer "+tok)
	}
	resp, err := (&http.Client{Timeout: 10 * time.Second}).Do(req)
	if err != nil {
		s.t.Fatalf("%s %s: %v", method, path, err)
	}
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	if out != nil {
		if err := json.Unmarshal(b, out); err != nil && resp.StatusCode < 300 {
			s.t.Fatalf("decode %s: %v (%s)", path, err, b)
		}
	}
	return resp.StatusCode
}

type unitJSON struct {
	ID           string  `json:"id"`
	Name         string  `json:"name"`
	Connection   string  `json:"connection"`
	ControlState *string `json:"control_state"`
	Pump         *string `json:"pump_commanded"`
	Applied      *int    `json:"applied_program_version"`
	IsSimulated  bool    `json:"is_simulated"`
	Latest       *struct {
		Source string `json:"data_source"`
	} `json:"latest_readings"`
}

func (s *stack) units() []unitJSON {
	var r struct{ Units []unitJSON }
	if c := s.call("GET", "/api/v1/sites/"+s.prov.SiteID+"/units?limit=100", s.admin(), nil, &r); c != 200 {
		s.t.Fatalf("units: %d", c)
	}
	return r.Units
}

func (s *stack) unit(id string) unitJSON {
	for _, u := range s.units() {
		if u.ID == id {
			return u
		}
	}
	s.t.Fatalf("unit %s missing", id)
	return unitJSON{}
}

type incidentJSON struct {
	ID, UnitID, Code, Status, Severity, Title string
	UnitIDx                                   string `json:"unit_id"`
}

func (s *stack) incidents(state string) []map[string]any {
	var r struct{ Incidents []map[string]any }
	s.call("GET", "/api/v1/sites/"+s.prov.SiteID+"/incidents?state="+state, s.admin(), nil, &r)
	return r.Incidents
}

func (s *stack) waitUntil(timeout time.Duration, what string, cond func() bool) {
	s.t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if cond() {
			return
		}
		time.Sleep(50 * time.Millisecond)
	}
	s.t.Fatalf("timed out after %s waiting for: %s", timeout, what)
}

func (s *stack) allOnline(n int) bool {
	us := s.units()
	if len(us) != n {
		return false
	}
	for _, u := range us {
		if u.Connection != "ONLINE" {
			return false
		}
	}
	return true
}

// -------------------------------------------------------------- DB access

func (s *stack) db() *sql.DB {
	db, err := sql.Open("sqlite", "file:"+s.dbPath()+"?mode=ro&_pragma=busy_timeout(5000)")
	if err != nil {
		s.t.Fatal(err)
	}
	s.t.Cleanup(func() { db.Close() })
	return db
}

func (s *stack) count(q string, args ...any) int {
	var n int
	if err := s.db().QueryRow(q, args...).Scan(&n); err != nil {
		s.t.Fatalf("%s: %v", q, err)
	}
	return n
}

// seqRange returns, per (device, boot), the stored sequence numbers from the
// telemetry+event tables (they share one counter).
func (s *stack) storedSeqs() map[string]map[int64]bool {
	rows, err := s.db().Query(`SELECT device_id||'/'||boot_id, sequence_number FROM telemetry_snapshots UNION ALL SELECT device_id||'/'||boot_id, sequence_number FROM device_events`)
	if err != nil {
		s.t.Fatal(err)
	}
	defer rows.Close()
	out := map[string]map[int64]bool{}
	for rows.Next() {
		var k string
		var q int64
		_ = rows.Scan(&k, &q)
		if out[k] == nil {
			out[k] = map[int64]bool{}
		}
		out[k][q] = true
	}
	return out
}

// assertNoGapsNoDuplicates: every sequence 1..(current-slack) of the current
// boot of every device is stored exactly once. Duplicates are impossible by
// the UNIQUE constraint; the test also proves nothing was LOST.
func (s *stack) assertNoGapsNoDuplicates(slack int64) {
	s.t.Helper()
	have := s.storedSeqs()
	for _, d := range s.fleet.All() {
		st := d.Status()
		set := have[st.DeviceID+"/"+st.BootID]
		for q := int64(1); q <= st.Seq-slack; q++ {
			if !set[q] {
				s.t.Errorf("%s boot %s: sequence %d missing from SQLite (device is at %d, journal=%d)", st.DeviceID, st.BootID, q, st.Seq, st.JournalOcc)
				return
			}
		}
	}
	if dup := s.count(`SELECT COUNT(*) FROM (SELECT device_id,boot_id,sequence_number FROM telemetry_snapshots GROUP BY 1,2,3 HAVING COUNT(*)>1)`); dup != 0 {
		s.t.Errorf("%d duplicated telemetry keys", dup)
	}
}

// missingSeqs lists, per device, sequences <= (device seq - slack) of its
// current boot that are not yet in SQLite.
func (s *stack) missingSeqs(slack int64) map[string][]int64 {
	have := s.storedSeqs()
	out := map[string][]int64{}
	for _, d := range s.fleet.All() {
		st := d.Status()
		set := have[st.DeviceID+"/"+st.BootID]
		for q := int64(1); q <= st.Seq-slack; q++ {
			if !set[q] {
				out[st.DeviceID] = append(out[st.DeviceID], q)
			}
		}
	}
	return out
}

// waitNoLoss waits (bounded) until every record the devices have produced is
// durable in SQLite exactly once, and reports how long recovery took.
func (s *stack) waitNoLoss(timeout time.Duration, slack int64) time.Duration {
	s.t.Helper()
	start := time.Now()
	var last map[string][]int64
	for time.Since(start) < timeout {
		if last = s.missingSeqs(slack); len(last) == 0 {
			took := time.Since(start)
			s.assertNoGapsNoDuplicates(slack)
			return took
		}
		time.Sleep(100 * time.Millisecond)
	}
	s.t.Fatalf("records still missing from SQLite after %s: %v", timeout, last)
	return 0
}

func (s *stack) journalsDrained(max int) bool {
	for _, d := range s.fleet.All() {
		if d.Status().JournalOcc > max {
			return false
		}
	}
	return true
}

var prog1s = map[string]any{"mode": "TIMED_CYCLE", "on_duration_seconds": 1, "off_duration_seconds": 1, "max_continuous_on_seconds": 1, "require_reservoir_ok": true}

func strOr(s *string, d string) string {
	if s == nil {
		return d
	}
	return *s
}

var _ = strings.TrimSpace

// runEdgeOnce starts the edge and returns its combined output after it exits
// (used for start-up refusal tests).
func (s *stack) runEdgeOnce(extra map[string]string) (*exec.Cmd, string) {
	s.t.Helper()
	bin := buildEdge(s.t)
	env := os.Environ()
	set := map[string]string{
		"AEROLAB_SITE_ID": s.prov.SiteID, "AEROLAB_HTTP_ADDR": fmt.Sprintf("127.0.0.1:%d", freePort(s.t)), "AEROLAB_DB_PATH": filepath.Join(s.dir, "once.db"),
		"AEROLAB_MQTT_URL": s.prov.BrokerURL, "AEROLAB_MQTT_USER": seed.EdgeMQTTUser, "AEROLAB_MQTT_PASSWORD": s.prov.EdgePassword, "AEROLAB_PROVISION_FILE": s.prov.CredsFile,
	}
	for k, v := range extra {
		set[k] = v
	}
	for k, v := range set {
		env = append(env, k+"="+v)
	}
	cmd := exec.Command(bin, "serve")
	cmd.Env = env
	done := make(chan struct{})
	var out []byte
	go func() { out, _ = cmd.CombinedOutput(); close(done) }()
	select {
	case <-done:
	case <-time.After(10 * time.Second):
		_ = cmd.Process.Kill()
		<-done
	}
	return cmd, string(out)
}
